it('should enforce the resend interval and clear expired validations', async () => {
	plugins.hooks.register('email-confirmation-test', {
		hook: 'filter:email.send',
		method: async () => {},
	});
	try {
	const uid = userObj.uid;
	const email = 'test@example.org';
	const expiryMs = meta.config.emailConfirmExpiry * 24 * 60 * 60 * 1000;
	const intervalMs = meta.config.emailConfirmInterval * 60 * 1000;
	const firstCode = await db.get(`confirm:byUid:${uid}`);

	assert.strictEqual(await user.email.isValidationPending(uid), true);
	assert.strictEqual(await user.email.isValidationPending(uid, 'other@example.org'), false);
	const initialTtl = await user.email.getValidationExpiry(uid);
	assert(initialTtl > 0 && initialTtl <= expiryMs);
	assert.strictEqual(await user.email.canSendValidation(uid, email), false);

	await db.pexpireAt(`confirm:byUid:${uid}`, Date.now() + expiryMs - intervalMs - 1000);
	assert.strictEqual(await user.email.canSendValidation(uid, email), true);
	const secondCode = await user.email.sendValidationEmail(uid, email);
	assert.notStrictEqual(secondCode, firstCode);
	assert.strictEqual(await db.getObject(`confirm:${firstCode}`), null);

	await user.email.expireValidation(uid);
	assert.strictEqual(await user.email.isValidationPending(uid), false);
	assert.strictEqual(await user.email.getValidationExpiry(uid), null);
	assert.strictEqual(await db.getObject(`confirm:${secondCode}`), null);
	assert.strictEqual(await user.email.canSendValidation(uid, email), true);
	await user.email.sendValidationEmail(uid, email);
	} finally {
		plugins.hooks.unregister('email-confirmation-test', 'filter:email.send');
	}
});

